WITH base AS (SELECT o.id AS order_id, o.customer_id, o.created_at FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date >= DATE '2024-01-01'), qualifying AS (SELECT DISTINCT b.customer_id FROM base b JOIN order_items oi ON oi.order_id=b.order_id JOIN products p ON p.id=oi.product_id AND p.active JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 JOIN shipments sh ON sh.order_id=b.order_id WHERE sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days'), cl AS (SELECT b.customer_id, count(DISTINCT CASE WHEN pay.order_id IS NOT NULL THEN b.order_id END) AS captured_order_count, max(b.created_at) AS last_completed_at FROM base b LEFT JOIN payments pay ON pay.order_id=b.order_id AND pay.status='captured' GROUP BY b.customer_id), revenue AS (SELECT b.customer_id, sum((oi.quantity - COALESCE(r.quantity,0))*oi.unit_price) AS net_item_revenue FROM base b JOIN order_items oi ON oi.order_id=b.order_id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=b.order_id AND pay.status='captured') GROUP BY b.customer_id), discount AS (SELECT b.customer_id, sum(op.discount_amount) AS active_promotion_discount FROM base b JOIN order_promotions op ON op.order_id=b.order_id JOIN promotions pr ON pr.id=op.promotion_id AND pr.active GROUP BY b.customer_id), late AS (SELECT b.customer_id, count(DISTINCT b.order_id) AS late_shipment_count FROM base b JOIN shipments sh ON sh.order_id=b.order_id WHERE sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days' GROUP BY b.customer_id), risky AS (SELECT b.customer_id, count(DISTINCT ps.supplier_id) AS risky_supplier_count FROM base b JOIN order_items oi ON oi.order_id=b.order_id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 GROUP BY b.customer_id) SELECT c.id AS customer_id, c.region, c.segment, COALESCE(cl.captured_order_count,0) AS captured_order_count, COALESCE(rev.net_item_revenue,0)::numeric(20,2) AS net_item_revenue, COALESCE(disc.active_promotion_discount,0)::numeric(18,2) AS active_promotion_discount, COALESCE(late.late_shipment_count,0) AS late_shipment_count, COALESCE(risky.risky_supplier_count,0) AS risky_supplier_count, cl.last_completed_at FROM customers c JOIN qualifying q ON q.customer_id=c.id LEFT JOIN cl ON cl.customer_id=c.id LEFT JOIN revenue rev ON rev.customer_id=c.id LEFT JOIN discount disc ON disc.customer_id=c.id LEFT JOIN late ON late.customer_id=c.id LEFT JOIN risky ON risky.customer_id=c.id WHERE c.active;